urlset:
{%- for sitemap_entry in entries %}{% if not sitemap_entry.extra or not sitemap_entry.extra.redirect_to %}

    {{ sitemap_entry.permalink | escape_xml | safe }}
    {%- if sitemap_entry.updated %}
    {{ sitemap_entry.updated }}
    {%- endif %}
    {%- if langs | length > 1 %}
    {%- set_global key = sitemap_entry.permalink | trim_start_matches(pat=root) %}
    {%- for l in langs %}{% if l.code != dlang and key is starting_with(l.code ~ "/") %}{% set_global key = key | trim_start_matches(pat=l.code ~ "/") %}{% endif %}{% endfor %}
    {%- set_global vtags = [] %}{% set_global vurls = [] %}{% set_global xdef = "" %}
    {%- for l in langs %}{% if l.code == dlang %}{% set u = root ~ key %}{% else %}{% set u = root ~ l.code ~ "/" ~ key %}{% endif %}
    {%- if u in all %}{% set_global vtags = vtags | concat(with=l.hreflang | default(value=l.code)) %}{% set_global vurls = vurls | concat(with=u) %}{% if l.code == dlang %}{% set_global xdef = u %}{% endif %}{% endif %}{% endfor %}
    {%- if vurls | length > 1 %}
    {%- for vu in vurls %}

    {%- endfor %}
    {%- if xdef %}

    {%- endif %}
    {%- endif %}
    {%- endif %}

{%- endif %}{% endfor %}
